"<td>日時で分けた回<br><button class=\"md-btn md-btn-sm\" data-act=\"periodEdit\" data-arg=\"{0}\">直す</button> <button class=\"md-btn md-btn-sm\" data-act=\"scoreDel\" data-arg=\"{1}\">消す</button></td>" = "<td>Rounds by date-time<br><button class=\"md-btn md-btn-sm\" data-act=\"periodEdit\" data-arg=\"{0}\">Edit</button> <button class=\"md-btn md-btn-sm\" data-act=\"scoreDel\" data-arg=\"{1}\">Delete</button></td>",
